insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('28d79476-50cc-46c9-be37-0ad56156f92f', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Un grupo de estudiantes quería determinar la longitud de larvas de cucarrón que eran seleccionadas como alimento por una especie de ave. Para ello les ofrecieron una muestra de 500 larvas, distribuidas por igual en 11 categorías de tamaño, entre 10 mm y 60 mm. Anotaron cuáles larvas fueron depredadas por las aves y con esta información calcularon el porcentaje de larvas consumidas en cada categoría de tamaño, según se muestra en la gráfica.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b2-q97.webp" style="min-width:490px" loading="lazy" alt="Porcentaje de larvas consumidas según su longitud, entre 10 y 60 mm."><figcaption>Porcentaje de larvas consumidas según su longitud, entre 10 y 60 mm. Desliza para ver la figura completa.</figcaption></figure><p>Después de analizar los resultados, los estudiantes concluyen: la especie de ave prefiere larvas de cucarrón de una longitud entre 30 mm y 45 mm.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('78484de5-3065-45aa-b519-1e622ba3325c', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En la especie de caracoles de agua dulce Potamopyrgus antipodarum, hay poblaciones que se reproducen sexualmente y otras asexualmente por clonación somática. Es decir, son copias idénticas de su progenitor. Los caracoles de esta especie son generalmente parasitados por un tipo de gusano plano. En una investigación, se encontró que en las poblaciones de caracoles que se reproducen asexualmente hay un mayor porcentaje de mortalidad causada por estos gusanos planos.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9790fe88-9b6a-4403-a768-218672207b70', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Una región rural cuenta con gran variedad de flora y fauna, entre ellas aves migratorias. Se evalúa la posibilidad de implementar el uso de energías renovables para obtener energía eléctrica, con el fin de reducir el impacto negativo que presenta el uso de combustibles fósiles. Dentro de los aspectos para tener en cuenta, se encuentran los que se mencionan en la tabla, en la que se comparan opciones de energías renovables con las que cuenta el lugar.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Tipo</th><th scope="col">Requerimientos</th><th scope="col">Cubrimiento de la necesidad energética de la región (%)</th><th scope="col">Impacto ambiental</th></tr></thead><tbody><tr><th scope="row">Hidráulica (ríos o lagos)</th><td>Formación de represas artificiales</td><td>78</td><td>Inundaciones, pérdida de bosques y de hábitat de animales.</td></tr><tr><th scope="row">Eólica (viento)</th><td>Vientos superiores a los 13 km/h</td><td>82</td><td>Generan exceso de ruido permanente, atraen rayos, peligro para las aves.</td></tr><tr><th scope="row">Solar (luz del sol)</th><td>Disponibilidad de luz solar</td><td>74</td><td>Empleo de sustancias peligrosas en la fabricación de las celdas.</td></tr></tbody></table></div><p>En la figura se muestra la forma como quedarían los montajes de los tres tipos de energías renovables.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b2-qenergia.webp" style="min-width:720px" loading="lazy" alt="Represa de central hidroeléctrica, central eólica y celdas solares."><figcaption>Represa de central hidroeléctrica, central eólica y celdas solares. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('b2c44106-f3ef-41a3-a55e-bf77bf71e989', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En la figura se observa una pirámide trófica de un ecosistema marino.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b2-q103.webp" style="min-width:570px" loading="lazy" alt="Pirámide marina: productores, herbívoros y cuatro niveles de carnívoros; descomponedores reciben materia de todos los niveles."><figcaption>Pirámide marina: productores, herbívoros y cuatro niveles de carnívoros; descomponedores reciben materia de todos los niveles. Desliza para ver la figura completa.</figcaption></figure><p>En este ecosistema se ha reducido drásticamente la población de delfines, tiburones y calamares debido a la caza indiscriminada de estos animales.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('84d86fa1-f285-4d6d-99b2-39f573985bc8', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>El esquema muestra el ciclo del oxígeno y el transporte de nutrientes en un ecosistema marino.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b2-q104.webp" style="min-width:700px" loading="lazy" alt="Intercambio de oxígeno y nutrientes entre capas de agua, productores, consumidores y comunidad bentónica."><figcaption>Intercambio de oxígeno y nutrientes entre capas de agua, productores, consumidores y comunidad bentónica. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('02927d8e-5d28-4ac2-86a2-40fb90c148ba', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Un grupo de científicos realizó el siguiente experimento:</p><ol><li>Seleccionaron 10 chimpancés jóvenes y 10 chimpancés adultos.</li><li>Le mostraron a cada chimpancé un video de otro chimpancé resolviendo un rompecabezas de madera.</li><li>Luego de ver el video, midieron el tiempo que le tomó a cada chimpancé resolver el mismo rompecabezas.</li><li>Compararon los tiempos promedio entre chimpancés adultos y chimpancés jóvenes.</li></ol>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('90277836-df38-438c-b8be-7740c30943cc', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>La fiebre chikungunya es una enfermedad viral transmitida al ser humano principalmente por la picadura de los mosquitos Aedes aegypti o Aedes albopictus infectados con este virus.</p><p>Algunas de las medidas preventivas para esta enfermedad son el uso de repelentes y el control de su reproducción. Una de las sustancias empleadas en los repelentes es la N,N-dietil-3-metilbenzamida, una sustancia que bloquea el olfato de los mosquitos y les impide rastrear compuestos presentes en el sudor o aliento de las personas. Al no localizar a las personas, los mosquitos no pueden picarlas. A continuación se muestran los resultados de un estudio que estimó las horas de protección contra picaduras de mosquitos, de un repelente con distinta concentración de N,N-dietil-3-metilbenzamida.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Concentración del compuesto (% p/v)</th><th scope="col">Tiempo de protección aproximado (horas)</th></tr></thead><tbody><tr><th scope="row">5%</th><td>2</td></tr><tr><th scope="row">10%</th><td>4</td></tr><tr><th scope="row">15%</th><td>6</td></tr><tr><th scope="row">30%</th><td>8</td></tr><tr><th scope="row">100%</th><td>10</td></tr></tbody></table></div><p>Por otra parte, como los mosquitos de estas especies se reproducen dejando sus huevos en aguas estancadas, una manera de controlar su reproducción es eliminar cualquier lugar donde puedan depositarse este tipo de aguas.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('6024f762-5ce0-44fe-a1ac-d54669f90e1f', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>El transporte celular es el intercambio de sustancias entre el interior celular a través de la membrana celular. En la tabla se describen algunos procesos de transporte.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Tipo de transporte</th><th scope="col">Descripción</th></tr></thead><tbody><tr><th scope="row">Difusión simple</th><td>Las sustancias pasan a través de la membrana celular, sin ayuda de ningún tipo de transportador.</td></tr><tr><th scope="row">Exocitosis</th><td>Expulsión de sustancias desde el interior de la célula hasta el exterior de esta.</td></tr><tr><th scope="row">Canales de transporte</th><td>Las sustancias atraviesan la membrana por canales proteicos de transporte.</td></tr><tr><th scope="row">Difusión facilitada</th><td>Las sustancias atraviesan la membrana celular por la acción de proteínas que las transportan.</td></tr></tbody></table></div><p>La figura muestra una sustancia atravesando la membrana celular.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b2-q109.webp" style="min-width:560px" loading="lazy" alt="Tres etapas de una vesícula que se acerca a la membrana, se fusiona con ella y libera su contenido al exterior."><figcaption>Tres etapas de una vesícula que se acerca a la membrana, se fusiona con ella y libera su contenido al exterior. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('a1ce62af-df9f-45fb-a683-f9a8a3f37f12', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Pedro quiere identificar cómo ayuda el cloro a prevenir la llegada de algas verdes al agua estancada. Para esto va a tomar diferentes recipientes de la misma forma, material y cantidad de agua estancada, a los cuales les adicionará diferentes cantidades de cloro. Posteriormente, medirá el tiempo en que aparecen las primeras algas verdes.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('a4b82066-2f2f-4f97-88be-f9bc5ca07861', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En la tabla se muestran dos tipos de tejidos presentes en las plantas y su principal función.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Tejido</th><th scope="col">Función</th></tr></thead><tbody><tr><th scope="row">Floema</th><td>Encargado del transporte de nutrientes orgánicos e inorgánicos, entre ellos glucosa, producidos por las partes fotosintéticas de la planta, hacia las raíces.</td></tr><tr><th scope="row">Xilema</th><td>Encargado del transporte de agua, sales minerales y otros nutrientes disponibles en el suelo, desde la raíz hasta las hojas de las plantas donde se realiza la fotosíntesis.</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9f0f95e8-fe00-4bfd-8bdb-6f7b892654e6', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Un estudiante tiene esta hipótesis: «Las plantas de girasol crecen mejor en climas cálidos, y el nitrógeno (N) y el fósforo (P) son nutrientes fundamentales para el éxito en el crecimiento de las flores».</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('0c07e7d9-f5b3-41c9-999e-1aa20e9171fe', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>La tabla muestra las características de cuatro tipos de transporte celular.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Transporte</th><th scope="col">Descripción</th></tr></thead><tbody><tr><th scope="row">Ósmosis</th><td>Transporte de agua a través de la membrana: el agua se mueve de un compartimiento de mayor concentración de agua a uno de menor concentración; no hay gasto de energía.</td></tr><tr><th scope="row">Transporte activo</th><td>Iones pequeños (como sodio o potasio) son transportados a través de proteínas conocidas como bombas; se gasta energía para transportarlos.</td></tr><tr><th scope="row">Endocitosis</th><td>Partículas son transportadas desde el exterior hacia el interior de la célula utilizando vesículas.</td></tr><tr><th scope="row">Exocitosis</th><td>Expulsión o secreción de sustancias hacia el exterior a través de la fusión de vesículas del citoplasma con la membrana celular.</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('dc988361-f1bd-486c-901f-e0190c2ff620', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Un grupo de científicos quiere determinar si existe competencia por el alimento entre las dos especies de peces. Ellos tienen la hipótesis de que entre las dos especies existe una fuerte competencia por el alimento, pero que se han adaptado a consumir el alimento en horarios distintos disminuyendo así la competencia. Ellos obtuvieron los resultados que se muestran en la gráfica:</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b2-q114.webp" style="min-width:450px" loading="lazy" alt="Alimentación promedio de dos especies de peces a lo largo del día; ambas consumen algas en horarios superpuestos."><figcaption>Alimentación promedio de dos especies de peces a lo largo del día; ambas consumen algas en horarios superpuestos. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('b8397a18-57b1-4cd6-be77-f893ff413117', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>La figura muestra una parte del proceso de meiosis I, indispensable en la formación de gametos.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b2-q115.webp" style="min-width:720px" loading="lazy" alt="Profase I con entrecruzamiento, metafase I, anafase I y telofase I."><figcaption>Profase I con entrecruzamiento, metafase I, anafase I y telofase I. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('92045dd4-09b8-43fa-9287-84c8cfbcc142', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En un río contaminado por mercurio, hay una especie de pez 1 que tiene niveles muy bajos de mercurio respecto a la especie de pez 2. Unos investigadores estudiaron si las fuentes alimenticias de cada especie influyen en el contenido de mercurio en los peces teniendo en cuenta que la especie de pez 1 se alimenta de algas y la especie de pez 2 se alimenta de animales pequeños. A continuación se presenta un esquema de los pasos de la investigación:</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Paso</th><th scope="col">Descripción</th></tr></thead><tbody><tr><th scope="row">Pregunta</th><td>¿La fuente de alimentación de las dos especies de peces influye en que la especie 1 tenga menor contenido de mercurio?</td></tr><tr><th scope="row">¿Qué se hizo?</th><td>Se determinó la cantidad de alimento que consume diariamente cada pez.</td></tr><tr><th scope="row">Resultados</th><td>Se observó que la especie de pez 1 consume más alimento al día.</td></tr><tr><th scope="row">Conclusión</th><td>No se encontró una relación entre el contenido de mercurio y la fuente alimenticia de las dos especies de peces.</td></tr></tbody></table></div>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7dcd4dc5-3af6-4b47-b265-0aa7992e0f54', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '28d79476-50cc-46c9-be37-0ad56156f92f', 'Ecosistemas y ciclos',
  'De acuerdo con la información anterior, ¿los datos obtenidos por los estudiantes respaldan su conclusión?',
  array['Sí, porque los porcentajes más altos de larvas consumidas están en ese rango.', 'No, porque las larvas entre 10 mm y 15 mm tienen mayor aporte de proteínas para las aves.', 'Sí, porque los porcentajes de consumo fueron iguales en todas las longitudes de larvas.', 'No, porque las aves prefieren a las larvas gordas y lentas porque las cazan fácilmente.'],
  'Compara las alturas de las barras dentro y fuera del intervalo.', 'publicada', 'modelo', '1d2afab257e6780b0ea5b534478a06c6', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7dcd4dc5-3af6-4b47-b265-0aa7992e0f54', 0, 'Las barras más altas corresponden al intervalo de 30 a 45 mm. La gráfica no mide contenido de proteínas ni rapidez de movimiento. El total de 500 no se divide exactamente entre 11; esa imprecisión del enunciado no cambia la comparación de barras.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '64879940-d09d-4ce0-8ee0-bf11934dd594', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'genetica-y-herencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '78484de5-3065-45aa-b519-1e622ba3325c', 'Genética y herencia',
  '¿Por qué las poblaciones que provienen de reproducción asexual tendrían una mayor tasa de mortalidad por infecciones con el gusano plano?',
  array['Porque tienen un menor número de caracoles en el ecosistema.', 'Porque su gestación es más lenta que en los que nacen de una reproducción sexual.', 'Porque tienen menor variabilidad genética.', 'Porque carecen de sistema inmune.'],
  'Relaciona clonación y diversidad genética.', 'publicada', 'modelo', '5061a860774605eef5e8c88407d7ce1e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('64879940-d09d-4ce0-8ee0-bf11934dd594', 2, 'Al ser copias genéticamente muy semejantes, comparten susceptibilidad frente al parásito. La reproducción sexual genera combinaciones que pueden aumentar la diversidad de respuestas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '0fe3ca88-930b-4550-aaf4-b6a599ce52c6', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '9790fe88-9b6a-4403-a768-218672207b70', 'Ecosistemas y ciclos',
  'Con base en la información suministrada, ¿qué tipo de energía se recomienda más para esta región, teniendo en cuenta que esta debe presentar el menor impacto al ambiente y a la comunidad?',
  array['Hidráulica.', 'Eólica.', 'Solar.', 'Combustible fósil.'],
  'Compara los impactos descritos sobre el ecosistema de esa región.', 'publicada', 'modelo', 'b3485bfb8cd6e306876b037881f8bfb8', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0fe3ca88-930b-4550-aaf4-b6a599ce52c6', 2, 'Según los impactos enumerados en la tabla, la solar evita inundar hábitats y el riesgo local para aves asociado a las otras alternativas. El ejercicio compara esos efectos, no afirma que fabricar paneles carezca de impacto.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4a985fae-ac46-4285-b679-807c44689dd0', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '9790fe88-9b6a-4403-a768-218672207b70', 'Ecosistemas y ciclos',
  'Como se observa en la tabla, ninguna de las energías propuestas satisface las necesidades energéticas de la región. ¿Qué deben hacer los habitantes de la región para que la energía disponible, de cualquier tipo, logre un cubrimiento total?',
  array['Utilizar únicamente la energía que se necesita y evitar desperdiciarla.', 'Aumentar la producción de vientos en la región, para que se produzca más energía y aumente su cubrimiento.', 'Aumentar las horas de luz al día para captar más energía con los paneles.', 'Instalar, de forma independiente, el tipo de energía que requiera cada vivienda de acuerdo con su necesidad.'],
  'Busca una acción que reduzca la demanda sin alterar fenómenos naturales.', 'publicada', 'modelo', '6578d844a73c7a9b941366b58144d946', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4a985fae-ac46-4285-b679-807c44689dd0', 0, 'Reducir el desperdicio disminuye la demanda que debe cubrir la energía disponible. Las personas no pueden aumentar las horas de luz o producir viento a voluntad, y cambiar la distribución por viviendas no demuestra que alcance el suministro.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a1fec6a3-be02-438e-b45f-631f7e5f0342', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'cuerpo-humano'),
  (select id from public.lotes where codigo = '2026-B'),
  '9790fe88-9b6a-4403-a768-218672207b70', 'Sistemas del cuerpo humano',
  'El exceso de ruido causado por las centrales eólicas causa problemas auditivos en la población. ¿Qué otros efectos en su salud pueden padecer los habitantes de la región por esta causa?',
  array['Infecciones respiratorias agudas.', 'Alteraciones del sistema nervioso central.', 'Quemaduras graves con sangrado en la piel.', 'Pérdida de la movilidad muscular.'],
  'Distingue los efectos del ruido de los de agentes infecciosos o quemaduras.', 'publicada', 'modelo', 'b1dc170344845caa939bf4496c90f014', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a1fec6a3-be02-438e-b45f-631f7e5f0342', 1, 'La exposición a ruido excesivo puede asociarse con estrés y alteraciones del sueño, efectos vinculados al sistema nervioso. Las demás opciones no corresponden al mecanismo planteado.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '6e0db7d0-2498-47b3-bc22-c1c26b359a45', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  'b2c44106-f3ef-41a3-a55e-bf77bf71e989', 'Ecosistemas y ciclos',
  'Con base en la información de la pirámide, ¿qué ocurrirá si se extinguen los delfines, tiburones y calamares de este ecosistema?',
  array['Los descomponedores disminuirán considerablemente porque no tendrían alimento, y esto afectaría la dinámica de los otros niveles.', 'Los productores primarios no tendrían alimento y desaparecerían porque el ecosistema dejaría de recibir energía solar.', 'Los carnívoros del segundo nivel aumentarían en número de individuos porque no tendrían depredadores.', 'Los carnívoros del primer nivel aumentarían en número de individuos, porque se alimentarían de los carnívoros de segundo nivel.'],
  'Sigue la relación entre los niveles superiores y sus presas.', 'publicada', 'modelo', 'ca1f63600b1a2bd8a5e5e2d2ec4a192d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6e0db7d0-2498-47b3-bc22-c1c26b359a45', 2, 'En la pirámide, al desaparecer los carnívoros superiores disminuye la presión de depredación sobre los peces del segundo nivel de carnívoros. Los productores siguen recibiendo luz y los descomponedores materia de otros niveles.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '3f0cebbc-a4cd-41d7-858f-98c0f04f9c42', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '84d86fa1-f285-4d6d-99b2-39f573985bc8', 'Ecosistemas y ciclos',
  'El ciclo del oxígeno y el flujo de nutrientes mantienen un equilibrio en el ecosistema marino, porque',
  array['la materia orgánica en descomposición retorna el oxígeno al agua y se queda almacenada en el fondo marino.', 'hay desplazamiento de oxígeno en las dos capas de agua y nutrientes para los distintos niveles tróficos.', 'la concentración de oxígeno en la capa superior es mayor y crea una barrera para que los organismos de las capas inferiores no emerjan.', 'el exceso de oxígeno y de nutrientes de las capas del mar se filtran en el agua dulce del río.'],
  'Lee el sentido de las flechas de oxígeno y materia orgánica.', 'publicada', 'modelo', '5afe25617e219182e518f75905a73df9', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3f0cebbc-a4cd-41d7-858f-98c0f04f9c42', 1, 'Las flechas muestran intercambios entre capas y disponibilidad de nutrientes para los organismos. La descomposición consume oxígeno en el esquema; no constituye una barrera que impida el movimiento de los animales.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4dd44d18-4301-4253-97cd-a90fc7a8f826', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'evolucion'),
  (select id from public.lotes where codigo = '2026-B'),
  '02927d8e-5d28-4ac2-86a2-40fb90c148ba', 'Evolución y biodiversidad',
  'Con base en la información anterior, ¿cuál de las siguientes es una pregunta de investigación asociada al experimento?',
  array['¿Pueden los chimpancés jóvenes resolver más rápido el rompecabezas, si ven a la madre chimpancé armando el rompecabezas en el video?', '¿Los chimpancés adultos resuelven más rápido que los jóvenes el rompecabezas luego de ver el video de un chimpancé resolviéndolo?', '¿Pueden los chimpancés adultos elegir el rompecabezas que más les gusta armar frente a otros que no les gustan?', '¿Los chimpancés jóvenes sufren de más estrés que los chimpancés adultos cuando están en cautiverio?'],
  'Identifica la variable comparada y el resultado medido.', 'publicada', 'modelo', '9807ab6b950c355106a517860e58be1b', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4dd44d18-4301-4253-97cd-a90fc7a8f826', 1, 'Se comparan dos grupos de edad bajo la misma tarea y se mide tiempo de resolución. No se varía la identidad de la madre ni se miden preferencias o estrés.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '34f79922-bd7b-4a2d-be50-f752c17ba3e2', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '90277836-df38-438c-b8be-7740c30943cc', 'Ecosistemas y ciclos',
  'Teniendo en cuenta la información anterior, ¿cuál de las siguientes preguntas relacionadas con la problemática puede orientar una investigación en el área de las ciencias naturales?',
  array['¿A cuántas personas les gustaría que el gobierno aumentara el número de propaganda y publicidad orientadas a prevenir el virus chikungunya?', '¿Cómo afecta la presencia del virus chikungunya en Colombia la actividad laboral de personas de diferentes regiones del país?', '¿Cuál es la estructura química de otras sustancias capaces de repeler las especies de mosquito que transmiten el chikungunya?', '¿Cuánto les cuesta a las empresas de salud los gastos médicos de pacientes infectados por chikungunya en Colombia?'],
  'Identifica qué pregunta estudia propiedades de sustancias y organismos.', 'publicada', 'modelo', '6c405615f09883f1871383fa83d46a2e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('34f79922-bd7b-4a2d-be50-f752c17ba3e2', 2, 'La estructura química y el efecto de sustancias sobre los mosquitos son objetos de estudio de las ciencias naturales. Las demás preguntas se centran en preferencias, actividad laboral o costos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '0120cf18-7c26-4b07-b879-ef49e6d9e331', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '90277836-df38-438c-b8be-7740c30943cc', 'Ecosistemas y ciclos',
  'De acuerdo con lo anterior, ¿cuál de las siguientes gráficas representa adecuadamente los resultados de la tabla?',
  array['<img src="img/figuras/bio/b2-q107-a.webp" style="width:100%;max-width:440px" alt="Gráfica del cuadernillo que relaciona concentración del repelente y tiempo de protección" loading="lazy">', '<img src="img/figuras/bio/b2-q107-b.webp" style="width:100%;max-width:440px" alt="Gráfica del cuadernillo que relaciona concentración del repelente y tiempo de protección" loading="lazy">', '<img src="img/figuras/bio/b2-q107-c.webp" style="width:100%;max-width:440px" alt="Gráfica del cuadernillo que relaciona concentración del repelente y tiempo de protección" loading="lazy">', '<img src="img/figuras/bio/b2-q107-d.webp" style="width:100%;max-width:440px" alt="Gráfica del cuadernillo que relaciona concentración del repelente y tiempo de protección" loading="lazy">'],
  'Verifica los nombres de ambos ejes y al menos dos pares de datos.', 'publicada', 'modelo', '410597ecf3908ae8dce3c07d03ee1940', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0120cf18-7c26-4b07-b879-ef49e6d9e331', 0, 'La gráfica correcta ubica concentración en el eje horizontal y horas en el vertical, con pares (5,2), (10,4), (15,6), (30,8) y (100,10). Las otras representaciones alteran los valores, los rótulos o el tipo de comparación.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7f703ae8-a998-42f8-ac05-9a6d0728ab51', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '90277836-df38-438c-b8be-7740c30943cc', 'Ecosistemas y ciclos',
  'De acuerdo con lo anterior, reducir o eliminar botellas de agua abiertas, estanques y albercas de lugares cerca de las casas es una medida efectiva para prevenir el chikungunya, porque',
  array['cuando hay más disponibilidad de agua las personas pueden contagiarse unas a otras cuando se dan la mano.', 'se eliminan fuentes de criadero del mosquito responsable de propagar el virus.', 'el agua puede evaporar los huevos del mosquito y hacer que el virus del chikungunya se disperse por el aire.', 'al consumir abundante cantidad de agua se puede adquirir el virus del chikungunya.'],
  'Relaciona el agua acumulada con el ciclo de vida del vector.', 'publicada', 'modelo', 'ed1cdf61bc365f8fee8239e596cc192b', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7f703ae8-a998-42f8-ac05-9a6d0728ab51', 1, 'Eliminar depósitos de agua estancada reduce lugares donde se reproduce el mosquito vector. En el mecanismo descrito, el virus se transmite por picaduras, no por beber agua o darse la mano.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '07c83400-c574-4ed2-943c-e5502045b2e7', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'celula'),
  (select id from public.lotes where codigo = '2026-B'),
  '6024f762-5ce0-44fe-a1ac-d54669f90e1f', 'Célula y sus procesos',
  'Con base en la información anterior, ¿qué tipo de transporte celular se presenta en la figura?',
  array['Difusión simple.', 'Exocitosis.', 'Canales de transporte.', 'Difusión facilitada.'],
  'Sigue el contenido de la vesícula desde el interior hacia el exterior.', 'publicada', 'modelo', 'edccc660bf9a6b4ecc15e66f2e7b0f9a', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('07c83400-c574-4ed2-943c-e5502045b2e7', 1, 'La vesícula se fusiona con la membrana y libera sustancias fuera de la célula. Ese proceso corresponde a la exocitosis descrita en la tabla.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4f26f87e-eb39-4c0d-93b5-75d0bf2507c0', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'celula'),
  (select id from public.lotes where codigo = '2026-B'),
  'a1ce62af-df9f-45fb-a683-f9a8a3f37f12', 'Célula y sus procesos',
  'Para entender el efecto del cloro, ¿qué información le falta a Pedro como referencia para analizar luego sus resultados?',
  array['Un recipiente con muchas algas y sin cloro ni agua.', 'Un recipiente con la misma cantidad de agua pero sin cloro.', 'Un recipiente con agua potable y totalmente sellado.', 'Recipientes de diferentes formas y diferentes materiales.'],
  'Busca un control que difiera solo en la variable que se estudia.', 'publicada', 'modelo', 'b32e111e4e5b84881bc17914ef482cc6', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4f26f87e-eb39-4c0d-93b5-75d0bf2507c0', 1, 'Un control con las mismas condiciones y sin cloro permite comparar el tiempo de aparición de algas con y sin el tratamiento. Cambiar el agua, el recipiente o el sellado introduciría otras variables.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '0001fc05-bc3c-4504-858a-55753f460323', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'celula'),
  (select id from public.lotes where codigo = '2026-B'),
  'a4b82066-2f2f-4f97-88be-f9bc5ca07861', 'Célula y sus procesos',
  'Teniendo en cuenta la información anterior, ¿por qué es importante el movimiento de fluidos a través del xilema de la planta?',
  array['Porque a partir de la glucosa transportada, la planta puede producir agua y minerales durante la fotosíntesis.', 'Porque a partir del agua transportada, la planta puede producir sales minerales durante la fotosíntesis para su desarrollo.', 'Porque a partir del agua y las sales minerales, la planta puede producir glucosa para su desarrollo, durante la fotosíntesis.', 'Porque a partir del transporte de glucosa y sales minerales, la planta puede llevar a cabo la fotosíntesis.'],
  'Identifica qué transporta el xilema y hacia qué órgano.', 'publicada', 'modelo', '5ff127ef0dc6c7e49742114b6b20938d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0001fc05-bc3c-4504-858a-55753f460323', 2, 'El xilema lleva agua y minerales hacia las hojas, lo que sostiene la fotosíntesis y el desarrollo. La glucosa se forma usando agua y dióxido de carbono con energía luminosa; las sales minerales no sustituyen al CO₂ como fuente de carbono.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '700ba213-a2b6-4685-92c4-6ab9f001d168', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'celula'),
  (select id from public.lotes where codigo = '2026-B'),
  '9f0f95e8-fe00-4bfd-8bdb-6f7b892654e6', 'Célula y sus procesos',
  'Si quiere comprobar su hipótesis, ¿cuál sería el mejor procedimiento para verificarla?',
  array['<img src="img/figuras/bio/b2-q112-a.webp" style="width:100%;max-width:440px" alt="Diseño experimental del cuadernillo con plantas de girasol, temperaturas y nutrientes" loading="lazy">', '<img src="img/figuras/bio/b2-q112-b.webp" style="width:100%;max-width:440px" alt="Diseño experimental del cuadernillo con plantas de girasol, temperaturas y nutrientes" loading="lazy">', '<img src="img/figuras/bio/b2-q112-c.webp" style="width:100%;max-width:440px" alt="Diseño experimental del cuadernillo con plantas de girasol, temperaturas y nutrientes" loading="lazy">', '<img src="img/figuras/bio/b2-q112-d.webp" style="width:100%;max-width:440px" alt="Diseño experimental del cuadernillo con plantas de girasol, temperaturas y nutrientes" loading="lazy">'],
  'Busca las cuatro combinaciones de temperatura y presencia de nutrientes.', 'publicada', 'modelo', '7eaa8cc720b8f1aca636afb798251dbf', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('700ba213-a2b6-4685-92c4-6ab9f001d168', 0, 'El diseño seleccionado compara plantas con y sin N y P tanto en clima frío como cálido, con mediciones repetidas. Así se pueden distinguir los efectos de temperatura y nutrientes, sin hacer que ambos cambien siempre juntos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '121b501d-e56f-4bcf-9353-542725612eb9', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'celula'),
  (select id from public.lotes where codigo = '2026-B'),
  '0c07e7d9-f5b3-41c9-999e-1aa20e9171fe', 'Célula y sus procesos',
  'De acuerdo con la tabla anterior, si un glóbulo blanco encuentra una bacteria perjudicial, ¿qué tipo de transporte utilizará para atraparla?',
  array['Endocitosis.', 'Ósmosis.', 'Transporte activo.', 'Exocitosis.'],
  'Determina la dirección del movimiento y el tamaño del material incorporado.', 'publicada', 'modelo', 'b305e22f2ee53bc680bf0900b6738f06', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('121b501d-e56f-4bcf-9353-542725612eb9', 0, 'La bacteria entra en una vesícula al ser englobada por la célula. Esta fagocitosis es una forma de endocitosis; no es transporte de agua o de iones ni expulsión al exterior.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '84e88fc2-0399-480f-91b5-0b7b0b2b2814', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  'dc988361-f1bd-486c-901f-e0190c2ff620', 'Ecosistemas y ciclos',
  'Con estos resultados, ellos notan que la hipótesis es falsa. ¿Cuál de las siguientes es una conclusión del estudio?',
  array['La especie 2 es más activa para consumir algas cuando estas no realizan la fotosíntesis y dejan de consumirlas cuando hay demasiada luz.', 'La especie 2 es más consumida por los individuos de la especie 1 en horas de la tarde y disminuye en la noche.', 'Existen horarios diferentes de alimentación entre las dos especies, y la especie 1 consume más algas en promedio que la especie 2.', 'La especie 1 tiene una alimentación promedio constante a lo largo del día y deja de alimentarse cuando no hay luz.'],
  'Contrasta todas las partes de cada conclusión con la gráfica.', 'borrador', 'modelo', '5cb627518a41904e29875bfc0575328f', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('84e88fc2-0399-480f-91b5-0b7b0b2b2814', 2, 'La especie 1 consume más algas, pero las curvas muestran alimentación simultánea durante gran parte del día. La opción que incluye ese dato también afirma horarios diferentes, pese a que el enunciado declara falsa la hipótesis de separación horaria. No hay una conclusión completamente inequívoca entre las opciones; se conserva para revisión docente.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '99177bda-615e-439e-96ed-d2286b926e2f', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'genetica-y-herencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'b8397a18-57b1-4cd6-be77-f893ff413117', 'Genética y herencia',
  'De acuerdo con la figura, ¿en cuál etapa de la meiosis I se produce la mayor parte de la variación genética para la formación de las células hijas?',
  array['Profase I.', 'Metafase I.', 'Anafase I.', 'Telofase I.'],
  'Ubica en la figura el intercambio de material genético.', 'publicada', 'modelo', 'fad155b91646f0a2e3e5b3ce8744d663', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('99177bda-615e-439e-96ed-d2286b926e2f', 0, 'La figura señala el entrecruzamiento e intercambio de ADN entre cromosomas en profase I. Ese intercambio genera nuevas combinaciones; la distribución independiente también contribuye a la variación durante la meiosis.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '2ae696aa-2791-4591-8b0d-8a278459a997', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '92045dd4-09b8-43fa-9287-84c8cfbcc142', 'Ecosistemas y ciclos',
  'Teniendo en cuenta la información anterior, la conclusión no se relaciona con el experimento. ¿Qué falencia se encuentra en el experimento planteado para esta investigación?',
  array['Se debía medir el número de peces de cada especie para poder calcular la cantidad de alimento que consume cada uno.', 'Se debía medir la cantidad de mercurio que contienen los alimentos que consume cada una de las especies.', 'Se debía medir el tamaño de los ojos de cada especie de pez, pues si son más grandes consumen más alimento.', 'Se debía medir el consumo humano de las distintas especies, porque afecta el contenido de mercurio en los peces.'],
  'Comprueba si las mediciones corresponden a la variable de la pregunta.', 'publicada', 'modelo', 'bb3f959362b4444a01d8416c51d5289c', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2ae696aa-2791-4591-8b0d-8a278459a997', 1, 'Medir solo cuánto alimento comen no permite relacionar la dieta con el mercurio acumulado. Falta determinar cuánto mercurio contienen las fuentes alimenticias.');

